<script setup lang="ts">
import type {SubscriptionAlertPolicy,LowQuotaThreshold} from '@papilio/api';
const model=defineModel<SubscriptionAlertPolicy>({required:true});
function threshold(rule:LowQuotaThreshold,key:"remaining_percent_bps"|"remaining_bytes",event:Event):void{const value=(event.target as HTMLInputElement).value;rule[key]=value===""?null:Number(value);}
function add():void{model.value.low_quota.push({code:'',mode:'any',remaining_percent_bps:null,remaining_bytes:null});}
</script>
<template><fieldset class="form-grid"><legend>Subscription alerts</legend><label class="check-row"><input v-model="model.enabled" type="checkbox"/>Enable generation-based subscription alerts</label><p class="hint-box">Each rule sends at most one notice per renewal generation. The first captured quota, expiry and price remain in the notice. Unlimited quota skips quota rules; services without expiry skip expiry rules. Enabling this policy replaces the legacy customer expiry warning.</p><fieldset v-for="(rule,index) in model.low_quota" :key="index" class="form-grid"><legend>Low quota rule {{index+1}}</legend><label class="field"><span>Stable rule code</span><input v-model="rule.code" required maxlength="32" pattern="[A-Za-z0-9_-]+"/></label><label class="field"><span>Threshold combination</span><select v-model="rule.mode"><option value="any">Any configured threshold</option><option value="all">All configured thresholds</option></select></label><label class="field"><span>Remaining percentage (basis points; 100 = 1%)</span><input :value="rule.remaining_percent_bps??''" type="number" min="0" max="10000" placeholder="Not configured" @input="threshold(rule,'remaining_percent_bps',$event)"/></label><label class="field"><span>Remaining bytes</span><input :value="rule.remaining_bytes??''" type="number" min="0" placeholder="Not configured" @input="threshold(rule,'remaining_bytes',$event)"/></label><button type="button" class="btn secondary" @click="model.low_quota.splice(index,1)">Remove quota rule</button></fieldset><button type="button" class="btn secondary" @click="add">Add quota rule</button><label v-for="(_,index) in model.expiry_hours" :key="index" class="field"><span>Expiry warning {{index+1}} (hours remaining)</span><input v-model.number="model.expiry_hours[index]" required type="number" min="1"/><button type="button" class="btn secondary" @click="model.expiry_hours.splice(index,1)">Remove expiry warning</button></label><button type="button" class="btn secondary" @click="model.expiry_hours.push(1)">Add expiry warning</button><label class="check-row"><input v-model="model.renewal_opportunity" type="checkbox"/>Notify about an available renewal when a rule is reached or quota/expiry ends</label><p>Notification templates, channels and delivery policy are configured separately. Rule codes identify notices: changing the code creates a new rule.</p></fieldset></template>
